package main

import (
	"fmt"
	"sync"

	ir "github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

func main() {
	aWins, bWins := 0, 0
	for round := 0; round < 200; round++ {
		idx := ir.New()
		idx.Append(ir.Block{Height: 1, Hash: "p1", Parent: "g"})
		a := ir.Block{Height: 2, Hash: "same", Parent: "p1", Txs: []string{"a", "b", "a"}}
		b := ir.Block{Height: 2, Hash: "same", Parent: "p1", Txs: []string{"a", "a", "b"}}
		start := make(chan struct{})
		var wg sync.WaitGroup
		for i := 0; i < 8; i++ {
			wg.Add(1)
			c := a
			if i%2 == 0 {
				c = b
			}
			go func(c ir.Block) { defer wg.Done(); <-start; idx.Append(c) }(c)
		}
		close(start)
		wg.Wait()
		if idx.Blocks[2].Txs[1] == "b" {
			aWins++
		} else {
			bWins++
		}
	}
	fmt.Printf("content-a wins=%d  content-b wins=%d (over 200 rounds)\n", aWins, bWins)
}
EOF
